<?php require __DIR__.'/../bootstrap.php';require_login();$id=current_user()['id'];$tid=(int)getv('id');$s=db()->prepare('SELECT * FROM tasks WHERE id=? AND user_id=?');$s->execute([$tid,$id]);$t=$s->fetch();if(!$t)exit('Task not found.');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();db()->prepare('UPDATE tasks SET title=?,description=?,status=?,priority=?,due_date=?,updated_at=NOW() WHERE id=? AND user_id=?')->execute([post('title'),post('description'),post('status'),post('priority'),post('due_date')?:null,$tid,$id]);redirect('/tasks/');}$title='Edit Task';require __DIR__.'/../includes/header.php';?><form class="card form-card" method="post"><?=csrf_field()?><label>Title<input name="title" value="<?=e($t['title'])?>" required></label><label>Description<textarea name="description" rows="6"><?=e($t['description'])?></textarea></label><div class="grid2"><label>Status<select name="status"><?php foreach(['Todo','In Progress','Completed'] as $v):?><option <?=$t['status']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>Priority<select name="priority"><?php foreach(['Low','Medium','High'] as $v):?><option <?=$t['priority']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>Due Date<input type="date" name="due_date" value="<?=e($t['due_date'])?>"></label></div><div class="actions"><button class="btn edit-btn" style="background:var(--brand)!important;color:#fff!important">Save Changes</button><button class="btn danger" type="submit" formaction="/tasks/delete/" formmethod="post" name="id" value="<?=$tid?>">Delete Task</button></div><p><a class="btn secondary small" href="/ai/?prompt=Task%20assist%3A%20help%20me%20improve%20this%20task">✨ AI Assist</a></p></form><?php require __DIR__.'/../includes/footer.php'; ?>